var num = 13;
var bezs, h;

function setup() {
	createCanvas(windowHeight * 210 / 297, windowHeight); // windowWidth, windowHeight
	describe("");
	h = ~~(width / 10);
	background("rgb(4, 4, 16)");
	noFill();
	strokeWeight(h/2);
	stroke("beige");
	rect(0, 0, width, height);
	colorMode(HSB);
	genForm(h);
}

function draw() {
	const IPB = 150; // intersections per bezier
	const TTF = IPB * bezs.length; // total frames
	const BID = (frameCount % TTF) / IPB;
	const t = fract(BID);
	// console.log(`${~~BID}, ${nf(t, 0, 2)}`)

	const bez = bezs[~~BID];
	const x = bezierPoint(bez.p1.x, bez.h1.x, bez.h2.x, bez.p2.x, t);
  const y = bezierPoint(bez.p1.y, bez.h1.y, bez.h2.y, bez.p2.y, t);
	const vec = createVector(
		bezierTangent(bez.p1.x, bez.h1.x, bez.h2.x, bez.p2.x, t),
  	bezierTangent(bez.p1.y, bez.h1.y, bez.h2.y, bez.p2.y, t)
	);
	const ang = vec.heading();
	stroke(((ang/TWO_PI*360)*0.5+220)%360, 75, 60+sin(ang/3-HALF_PI)*30)
	line(x, y, x, y+h);
}

function genForm(h, rd = 0.025) {
	noFill();
	stroke("azure");
	strokeWeight(1.5);
	// line(0, 0, width, height)
	const SW = ~~(width / 100);

	const a = createVector(h, h);
	const b = createVector(width - h, height - h);
	var vec = b.copy().sub(a).rotate(-HALF_PI);
	// console.log(vec, vec.heading())

	bezs = [];
	for (let i = 0, rot = random(-rd, rd); i < num; i++) {
		const f1 = i / num;
		const f2 = (i + 1) / num;

		const p1 = p5.Vector.lerp(a, b, f1)
		const p2 = p5.Vector.lerp(a, b, f2)

		const mul = i % 2 === 0 ? 1 : -1;
		const mf = num/3; // factor strecth help points in the middle
		const m1 = map(abs(i-num/2), 0, num/2, mf, 1);
		const m2 = map(abs(i+1-num/2), 0, num/2, mf, 1);
		const rt2 = random(-rd, rd);
		const vec1 = p5.Vector.sub(p2, p1).rotate(-HALF_PI + rot).mult(mul).mult(m1);
		const vec2 = p5.Vector.sub(p2, p1).rotate(-HALF_PI + rt2).mult(mul).mult(m2);
		rot = rt2;

		const h1 = p1.copy().add(vec1);
		const h2 = p2.copy().add(vec2);
		// console.log(vec, vec.heading());

		strokeWeight(1);
		bezier(
			p1.x, p1.y,
			h1.x, h1.y, // p1.x + vec.x, p1.y + vec.x,
			h2.x, h2.y, // p2.x + vec.x, p2.y + vec.x,
			p2.x, p2.y,
		);

		/*
		line(p1.x, p1.y, h1.x, h1.y)
		line(p2.x, p2.y, h2.x, h2.y)
		strokeWeight(SW);
		pt(p1);
		pt(h1);
		pt(h2);
		pt(p2);
		*/
		bezs.push({
			p1,
			h1,
			h2,
			p2
		});
	}

	strokeWeight(SW);
}

function pt(p) {
	point(p.x, p.y)
}
